2.  * DiscountPolicy is the seam consumers (and tests) substitute to control pricing.
3.  * Implementations must be deterministic and pure.
4.  */
5. export interface DiscountPolicy {
6.   /**
7.    * @param subtotalCents Sum of (unitPriceCents * quantity) across all lines, before any discount.
8.    * @returns Discount amount in cents as an integer. Cart.totals() clamps the returned value
9.    *          into [0, subtotalCents], so policies should aim for that range but are not
10.    *          required to — negative values are clamped to 0 and over-subtotal values are
11.    *          clamped down to subtotalCents.
12.    */
13.   computeDiscountCents(subtotalCents: number): number;
14. }
15. 
16. /** Default policy: no discount. */
17. export class NoDiscountPolicy implements DiscountPolicy {
18.   computeDiscountCents(_subtotalCents: number): number {
19.     return 0;
20.   }
21. }
22. 
23. /** Flat percentage off the subtotal, rounded down to the nearest cent. */
24. export class PercentageDiscountPolicy implements DiscountPolicy {
25.   constructor(private readonly percent: number) {
26.     if (!Number.isFinite(percent) || percent < 0 || percent > 100) {
27.       throw new RangeError(`percent must be between 0 and 100 (got ${percent})`);
28.     }
29.   }
30. 
31.   computeDiscountCents(subtotalCents: number): number {
32.     if (subtotalCents <= 0) return 0;
33.     return Math.floor((subtotalCents * this.percent) / 100);
34.   }
35. }
36. 
37. /** Flat amount off the subtotal. */
38. export class FixedAmountDiscountPolicy implements DiscountPolicy {
39.   constructor(private readonly amountCents: number) {
40.     if (!Number.isInteger(amountCents) || amountCents < 0) {
41.       throw new RangeError(
42.         `amountCents must be a non-negative integer (got ${amountCents})`,
43.       );
44.     }
45.   }
46. 
47.   computeDiscountCents(subtotalCents: number): number {
48.     if (subtotalCents <= 0) return 0;
49.     return Math.min(this.amountCents, subtotalCents);
50.   }
51. }
52. 
53. /**
54.  * Stacks multiple discount policies. Two stacking modes are supported:
55.  *
56.  * - `"sum"`: each child policy receives the original subtotal; results are summed
57.  *   then clamped to [0, subtotalCents] by the caller (Cart.totals).
58.  * - `"chain"`: each child policy is applied to the *remaining* subtotal after
59.  *   previous discounts (i.e. discounts compound). This is the typical "best
60.  *   coupon first" semantics. The discount value returned is the sum of the
61.  *   individual discount amounts, so the visible discountCents in CartTotals
62.  *   still represents the total reduction.
63.  */
64. export type StackingMode = "sum" | "chain";
65. 
66. export class CompositeDiscountPolicy implements DiscountPolicy {
67.   constructor(
68.     private readonly policies: readonly DiscountPolicy[],
69.     private readonly mode: StackingMode = "sum",
70.   ) {
71.     if (policies.length === 0) {
72.       throw new Error("CompositeDiscountPolicy requires at least one policy");
73.     }
74.   }
75. 
76.   computeDiscountCents(subtotalCents: number): number {
77.     if (subtotalCents <= 0) return 0;
78.     if (this.mode === "sum") {
79.       let total = 0;
80.       for (const p of this.policies) {
81.         total += Math.max(0, p.computeDiscountCents(subtotalCents));
82.       }
83.       return total;
84.     }
85.     let remaining = subtotalCents;
86.     let total = 0;
87.     for (const p of this.policies) {
88.       const step = Math.min(
89.         Math.max(0, p.computeDiscountCents(remaining)),
90.         remaining,
91.       );
92.       remaining -= step;
93.       total += step;
94.     }
95.     return total;
96.   }
