import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { CartConfig, CheckoutCollaborators } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";

const product = (id: string, priceCents = 1000, weightGrams?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: priceCents,
  weightGrams,
});

describe("Cart - line management", () => {
  it("add creates a new line", () => {
    const cart = new Cart();
    cart.add(product("a"), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add merges quantities for same product", () => {
    const cart = new Cart();
    cart.add(product("a"), 2);
    cart.add(product("a"), 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add rejects non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a"), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a"), -1)).toThrow(RangeError);
    expect(() => cart.add(product("a"), 1.5)).toThrow(RangeError);
  });

  it("add rejects negative unit price", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("remove deletes existing line and returns true", () => {
    const cart = new Cart();
    cart.add(product("a"), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown id", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(product("a"), 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the line", () => {
    const cart = new Cart();
    cart.add(product("a"), 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("missing", 1)).toThrow(
      "Product missing is not in the cart",
    );
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(product("a"), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("clear removes all lines", () => {
    const cart = new Cart();
    cart.add(product("a"), 2);
    cart.add(product("b"), 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const snap = cart.snapshot();
    snap[0]!.quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart - pricing pipeline (totals)", () => {
  it("computes subtotal as sum of unitPrice * quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 500), 2);
    cart.add(product("b", 300), 3);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(1900);
  });

  it("returns zeros for empty cart", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(0);
    expect(totals.totalCents).toBe(0);
  });

  it("applies discount policy and clamps to [0, subtotal]", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(200);
    expect(mockDiscount.computeDiscountCents).toHaveBeenCalledWith(1000);
  });

  it("clamps negative discount to 0", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps discount exceeding subtotal", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(9999),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(1000);
  });

  it("computes tax on the discounted subtotal", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      region: "US-CA",
    });
    cart.add(product("a", 1000), 1);
    cart.totals();
    // tax should receive discounted subtotal = 1000 - 200 = 800
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
  });

  it("computes shipping on discounted subtotal", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      shippingCalculator: mockShipping,
    });
    cart.add(product("a", 1000), 1);
    cart.totals();
    // shipping receives lines and discounted subtotal (1000 - 300 = 700)
    expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      700,
    );
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: () => 100,
    };
    const mockTax: TaxCalculator = {
      computeTaxCents: () => 90,
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: () => 500,
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      shippingCalculator: mockShipping,
    });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // subtotal=1000, discount=100, discountedSubtotal=900, tax=90, shipping=500
    expect(totals.totalCents).toBe(900 + 90 + 500);
  });

  it("defaults to US region", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(product("a"), 1);
    cart.totals();
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
  });
});

describe("Cart - async checkout", () => {
  it("refreshes prices when priceFetcher is provided", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(2000),
    };

    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("checks inventory and succeeds when available", async () => {
    const cart = new Cart();
    cart.add(product("a", 500), 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };

    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(1000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
  });

  it("throws InventoryError when item unavailable", async () => {
    const cart = new Cart();
    cart.add(product("a", 500), 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 0,
        reason: "discontinued",
      }),
    };

    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(2);
      expect(err.message).toBe("discontinued");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(product("a", 500), 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };

    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
      expect(err.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider when provided", async () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: () => 100,
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: () => 500,
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };

    const cart = new Cart({
      discountPolicy: mockDiscount,
      shippingCalculator: mockShipping,
    });
    cart.add(product("a", 1000), 1);

    const result = await cart.checkout({ asyncTaxProvider });
    // subtotal=1000, discount=100, discountedSubtotal=900, tax=10%*900=90, shipping=500
    expect(result.totals.taxCents).toBe(90);
    expect(result.totals.totalCents).toBe(900 + 90 + 500);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("combines priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
    const cart = new Cart({ region: "FR" });
    cart.add(product("a", 100), 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(500),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.2),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });
    // prices refreshed: 500 each * 2 = 1000 subtotal
    // no discount policy → discount = 0, discounted = 1000
    // tax = 20% of 1000 = 200
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.taxCents).toBe(200);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
  });

  it("works with no collaborators (defaults)", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.discountCents).toBe(0);
    expect(result.totals.taxCents).toBe(0);
    expect(result.totals.shippingCents).toBe(0);
    expect(result.totals.totalCents).toBe(1000);
  });

  it("returns the lines snapshot in the result", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const result = await cart.checkout();
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0].product.id).toBe("a");
    expect(result.lines[0].quantity).toBe(2);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(product("a"), 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("fetch failed");
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0],
    [100],
    [99999],
    [-50],
  ])("returns 0 for subtotal %i", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [101, "over 100"],
      [NaN, "NaN"],
      [Infinity, "Infinity"],
    ])("rejects %s (%s)", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it("accepts 0 and 100 boundary values", () => {
      expect(() => new PercentageDiscountPolicy(0)).not.toThrow();
      expect(() => new PercentageDiscountPolicy(100)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 1000 as 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("rounds down to nearest cent", () => {
      const policy = new PercentageDiscountPolicy(33);
      // 33% of 100 = 33, 33% of 101 = 33.33 → 33
      expect(policy.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("100% returns the full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when fixed amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(200)).toBe(200);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // 10% of 1000 = 100, plus fixed 100 = 200
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(80), new PercentageDiscountPolicy(80)],
        "sum",
      );
      // 80% + 80% = 160% of 1000 = 1600 (caller clamps to 1000)
      expect(composite.computeDiscountCents(1000)).toBe(1600);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativePolicy = { computeDiscountCents: () => -50 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // max(0, -50) + 100 = 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // 50% of 1000 = 500 off, remaining 500; 50% of 500 = 250 off; total discount = 750
      expect(composite.computeDiscountCents(1000)).toBe(750);
    });

    it("ordering matters in chain mode", () => {
      const composite1 = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(200), new PercentageDiscountPolicy(50)],
        "chain",
      );
      const composite2 = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // composite1: fixed 200 off 1000 → remaining 800; 50% of 800 = 400; total = 600
      expect(composite1.computeDiscountCents(1000)).toBe(600);
      // composite2: 50% of 1000 = 500 off → remaining 500; fixed min(200,500) = 200; total = 700
      expect(composite2.computeDiscountCents(1000)).toBe(700);
    });

    it("cannot exceed subtotal in chain mode", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(100), new PercentageDiscountPolicy(100)],
        "chain",
      );
      // 100% of 1000 = 1000 off → remaining 0; 100% of 0 → 0; total discount = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  describe("defaults to sum mode", () => {
    it("uses sum when mode is not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(50),
      ]);
      // sum: 10% of 1000 = 100 + 50 = 150
      expect(composite.computeDiscountCents(1000)).toBe(150);
    });
  });
});

