      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: -5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 2000, costCents: 800 },
      ],
      1200,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      expect(calc.computeShippingCents([line("a", undefined, 3)], 5000)).toBe(0);
    });

    it("selects first bracket when weight is within it", () => {
      // 1 item @ 400g = 400g → bracket upToGrams:500, cost 300
      expect(calc.computeShippingCents([line("a", 400)], 5000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      // 500g exactly → bracket upToGrams:500
      expect(calc.computeShippingCents([line("a", 500)], 5000)).toBe(300);
    });

    it("selects next bracket when just over boundary", () => {
      // 501g → bracket upToGrams:1000
      expect(calc.computeShippingCents([line("a", 501)], 5000)).toBe(500);
    });

    it("selects last bracket at its boundary", () => {
      // 2000g → bracket upToGrams:2000
      expect(calc.computeShippingCents([line("a", 2000)], 5000)).toBe(800);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // 2001g → overflow = 1200
      expect(calc.computeShippingCents([line("a", 2001)], 5000)).toBe(1200);
    });

    it("uses heaviest bracket cost when no overflow specified", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ]);
      // 5000g → overflow defaults to last bracket cost = 500
      expect(noOverflow.computeShippingCents([line("a", 5000)], 1000)).toBe(500);
    });

    it("sums weights across multiple lines and quantities", () => {
      // line a: 300g * 2 = 600g, line b: 200g * 3 = 600g → total 1200g → bracket upToGrams:2000
      const lines = [line("a", 300, 2), line("b", 200, 3)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(800);
    });

