describe("Cart - line management", () => {
  it("add creates a new line", () => {
    const cart = new Cart();
    cart.add(product("a"), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add merges quantities for same product", () => {
    const cart = new Cart();
    cart.add(product("a"), 2);
    cart.add(product("a"), 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add rejects non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a"), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a"), -1)).toThrow(RangeError);
    expect(() => cart.add(product("a"), 1.5)).toThrow(RangeError);
  });

  it("add rejects negative unit price", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("remove deletes existing line and returns true", () => {
    const cart = new Cart();
    cart.add(product("a"), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown id", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(product("a"), 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the line", () => {
    const cart = new Cart();
    cart.add(product("a"), 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("missing", 1)).toThrow(
      "Product missing is not in the cart",
    );
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(product("a"), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("clear removes all lines", () => {
    const cart = new Cart();
    cart.add(product("a"), 2);
    cart.add(product("b"), 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const snap = cart.snapshot();
    snap[0]!.quantity = 99;
